def last(arr, target, n):
    lo, hi = 0, n - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] < target:
            lo = mid + 1
        elif arr[mid] > target:
            hi = mid - 1
        else:
            # Move right to find the last occurrence
            if mid == n - 1 or arr[mid + 1] != target:
                return mid
            else:
                lo = mid + 1
    return -1
