        s = i
        while True:
            l = s * 2 + 1
            r = s * 2 + 2
            if l >= len(lst):
                break
            if r >= len(lst):
                if lst[l] < lst[s]:
                    lst[s], lst[l] = lst[l], lst[s]
                    s = l
                break
            if lst[l] < lst[r]:
                lst[s], lst[r] = lst[r], lst[s]
                s = r
