def min_jumps(arr, n):
    if n <= 1:
        return 0
    if arr[0] == 0:
        return -1

    # dp[i] stores the minimum number of jumps to reach index i
    dp = [float('inf')] * n
    dp[0] = 0

    for i in range(1, n):
        for j in range(1, min(arr[i], i - dp[i - 1])):
            if i - j >= 0:
                dp[i] = min(dp[i], dp[i - j] + 1)

    return dp[n - 1]
