def subset(arr, n):
    # If the array is empty or n is 0, no subsets are needed
    if n == 0 or len(arr) == 0:
        return 0

    # Base case: if only one element is needed, it's always 1 subset
    if n == 1:
        return 1

    # Use a set to keep track of unique subsets
    unique_subsets = set()

    # Generate all possible subsets using bit manipulation
    # Each bit in the n-bit integer represents whether an element is included
    for i in range(1 << n):
        subset_set = set()
        for j in range(n):
            if (i >> j) & 1:
                subset_set.add(arr[j])
        unique_subsets.add(frozenset(subset_set))

    # Find the minimum number of subsets to cover all elements
    # This is a set cover problem solved via brute force
    for k in range(1, n + 1):
        # Try to find k subsets that together cover all elements
        for combo in __import__('itertools').combinations(unique_subsets, k):
            combined_elements = set().union(*combo)
            if len(combined_elements) == n:
                return k

    return n
